SELECT CASE WHEN stock_qty >= 317 THEN 'high' WHEN stock_qty >= 193 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, SUM(stock_qty) AS total_stock_qty, SUM(SUM(stock_qty)) OVER (ORDER BY CASE WHEN stock_qty >= 317 THEN 'high' WHEN stock_qty >= 193 THEN 'mid' ELSE 'low' END) AS cumulative_stock_qty FROM products WHERE price < 350 GROUP BY CASE WHEN stock_qty >= 317 THEN 'high' WHEN stock_qty >= 193 THEN 'mid' ELSE 'low' END ORDER BY cumulative_stock_qty DESC
